def read_fasta(path):
    seqs=[]
    name=None; seq=[]
    for line in open(path):
        if line.startswith('>'):
            if name is not None: seqs.append((name,''.join(seq)))
            name=line[1:].strip().split()[0]; seq=[]
        else:
            seq.append(line.strip())
    if name is not None: seqs.append((name,''.join(seq)))
    return seqs
